import subprocess
import os
import random
def task_func(directory, file_list):
    if not file_list:
        return None

    filename = random.choice(file_list)
    file_path = os.path.join(directory, filename)

    try:
        process = subprocess.Popen(file_path)
        return process.poll()
    except Exception:
        return None

