import subprocess
import logging
import os
def task_func(filepath):
    if not os.path.exists(filepath):
        logging.error(f"File not found: {filepath}")
        raise FileNotFoundError(f"The file {filepath} does not exist.")

    try:
        subprocess.run(['g++', filepath], check=True, capture_output=True, text=True)
        logging.info(f"Compilation successful for {filepath}")
    except subprocess.CalledProcessError as e:
        logging.error(f"Compilation failed for {filepath}: {e.stderr}")
        raise e
    except FileNotFoundError as e:
        logging.error("Compiler 'g++' not found.")
        raise e

